-- AveroAI identity and metering foundation
-- PostgreSQL 15+. Apply once to a dedicated database using a migration runner
-- or psql. UUIDs are generated by the application; no extension is required.

BEGIN;

CREATE TABLE IF NOT EXISTS app_users (
  id uuid PRIMARY KEY,
  email text NOT NULL,
  status text NOT NULL DEFAULT 'pending'
    CHECK (status IN ('pending', 'active', 'suspended', 'deleted')),
  created_at timestamptz NOT NULL DEFAULT now(),
  updated_at timestamptz NOT NULL DEFAULT now(),
  CHECK (length(email) BETWEEN 3 AND 320),
  CHECK (email = lower(btrim(email)))
);

CREATE UNIQUE INDEX IF NOT EXISTS app_users_email_unique
  ON app_users (email);

CREATE INDEX IF NOT EXISTS app_users_status_created_idx
  ON app_users (status, created_at DESC);

CREATE TABLE IF NOT EXISTS email_verification_tokens (
  id uuid PRIMARY KEY,
  user_id uuid NOT NULL REFERENCES app_users(id) ON DELETE RESTRICT,
  token_hash bytea NOT NULL UNIQUE,
  expires_at timestamptz NOT NULL,
  consumed_at timestamptz,
  created_at timestamptz NOT NULL DEFAULT now(),
  CHECK (octet_length(token_hash) = 32),
  CHECK (expires_at > created_at),
  CHECK (consumed_at IS NULL OR consumed_at >= created_at)
);

CREATE INDEX IF NOT EXISTS email_verification_user_expiry_idx
  ON email_verification_tokens (user_id, expires_at DESC);

CREATE INDEX IF NOT EXISTS email_verification_expiry_unconsumed_idx
  ON email_verification_tokens (expires_at)
  WHERE consumed_at IS NULL;

CREATE TABLE IF NOT EXISTS account_limits (
  id uuid PRIMARY KEY,
  user_id uuid NOT NULL REFERENCES app_users(id) ON DELETE RESTRICT,
  policy_version text NOT NULL,
  period_starts_at timestamptz NOT NULL,
  period_ends_at timestamptz NOT NULL,
  max_requests bigint NOT NULL CHECK (max_requests >= 0),
  max_input_tokens bigint NOT NULL CHECK (max_input_tokens >= 0),
  max_output_tokens bigint NOT NULL CHECK (max_output_tokens >= 0),
  max_credits bigint NOT NULL CHECK (max_credits >= 0),
  created_at timestamptz NOT NULL DEFAULT now(),
  CHECK (period_ends_at > period_starts_at),
  CHECK (length(policy_version) BETWEEN 1 AND 80)
);

CREATE INDEX IF NOT EXISTS account_limits_user_period_idx
  ON account_limits (user_id, period_starts_at DESC, period_ends_at);

CREATE TABLE IF NOT EXISTS usage_reservations (
  request_id uuid PRIMARY KEY,
  user_id uuid NOT NULL REFERENCES app_users(id) ON DELETE RESTRICT,
  model_id text NOT NULL,
  reserved_credits bigint NOT NULL CHECK (reserved_credits >= 0),
  status text NOT NULL DEFAULT 'reserved'
    CHECK (status IN ('reserved', 'settled', 'released', 'expired', 'unmetered')),
  expires_at timestamptz NOT NULL,
  settlement_id uuid,
  created_at timestamptz NOT NULL DEFAULT now(),
  updated_at timestamptz NOT NULL DEFAULT now(),
  CHECK (length(model_id) BETWEEN 1 AND 200),
  CHECK (expires_at > created_at),
  CHECK (
    (status = 'settled' AND settlement_id IS NOT NULL) OR
    (status <> 'settled' AND settlement_id IS NULL)
  )
);

CREATE INDEX IF NOT EXISTS usage_reservations_user_created_idx
  ON usage_reservations (user_id, created_at DESC);

CREATE INDEX IF NOT EXISTS usage_reservations_expiry_idx
  ON usage_reservations (expires_at)
  WHERE status = 'reserved';

CREATE TABLE IF NOT EXISTS usage_ledger (
  id uuid PRIMARY KEY,
  user_id uuid NOT NULL REFERENCES app_users(id) ON DELETE RESTRICT,
  request_id uuid NOT NULL,
  idempotency_key text NOT NULL UNIQUE,
  entry_type text NOT NULL
    CHECK (entry_type IN ('usage_debit', 'usage_refund', 'credit_grant', 'credit_adjustment')),
  model_id text,
  input_tokens bigint,
  output_tokens bigint,
  credit_delta bigint NOT NULL,
  metadata_version smallint NOT NULL DEFAULT 1 CHECK (metadata_version > 0),
  metadata jsonb NOT NULL DEFAULT '{}'::jsonb,
  created_at timestamptz NOT NULL DEFAULT now(),
  CHECK (input_tokens IS NULL OR input_tokens >= 0),
  CHECK (output_tokens IS NULL OR output_tokens >= 0),
  CHECK (model_id IS NULL OR length(model_id) BETWEEN 1 AND 200),
  CHECK (jsonb_typeof(metadata) = 'object'),
  CHECK (
    (entry_type = 'usage_debit' AND credit_delta <= 0) OR
    (entry_type IN ('usage_refund', 'credit_grant') AND credit_delta >= 0) OR
    entry_type = 'credit_adjustment'
  )
);

CREATE INDEX IF NOT EXISTS usage_ledger_request_idx
  ON usage_ledger (request_id, created_at);

CREATE INDEX IF NOT EXISTS usage_ledger_user_created_idx
  ON usage_ledger (user_id, created_at DESC, id);

CREATE INDEX IF NOT EXISTS usage_ledger_model_created_idx
  ON usage_ledger (model_id, created_at DESC)
  WHERE model_id IS NOT NULL;

ALTER TABLE usage_ledger
  ADD CONSTRAINT usage_ledger_id_user_request_unique
  UNIQUE (id, user_id, request_id);

ALTER TABLE usage_reservations
  ADD CONSTRAINT usage_reservations_settlement_fk
  FOREIGN KEY (settlement_id, user_id, request_id)
  REFERENCES usage_ledger(id, user_id, request_id) ON DELETE RESTRICT;

-- Ledger history is append-only. Corrections must be compensating entries.
CREATE OR REPLACE FUNCTION reject_usage_ledger_mutation()
RETURNS trigger
LANGUAGE plpgsql
AS $$
BEGIN
  RAISE EXCEPTION 'usage_ledger is append-only; add a compensating entry';
END;
$$;

DROP TRIGGER IF EXISTS usage_ledger_no_update ON usage_ledger;
CREATE TRIGGER usage_ledger_no_update
  BEFORE UPDATE OR DELETE ON usage_ledger
  FOR EACH ROW EXECUTE FUNCTION reject_usage_ledger_mutation();

COMMIT;
